 const humanTypes={ordinary:'F',agrarian:'E',artisan:'D',merchant:'C',knight:'B',mage:'B',noble:'A',royal:'S',sovereign:'S',crown:'SS'};
 const rankTiers=['F','E','D','C','B','B','A','S'];
 const bound=n=>Math.max(0,Math.min(100,n));
 function grade(n){return order[[20,35,50,62,74,85,94].filter(x=>n>=x).length]}
 function species(s){const race=typeof s==='number'?s:s.race,r=rows[race];return {tier:r[0],name:RACES[race][0],strength:r[1],limit:r[2],habitat:Ecology.profile(race).label}}
 function hash(s,n){let x=Math.imul(((s.seed||0)^n)>>>0,2654435761);x=Math.imul(x^(x>>>16),2246822507);return(x^(x>>>13))>>>0}
 function starting(s){const x={resources:28+hash(s,7201)%58,access:25+hash(s,7202)%62,voice:18+hash(s,7204)%53};if(!s.socialOrigin?.migrated){if(s.heritage?.familyId==='demonKing'&&Species.isDemon(s.race)){x.access=88;x.voice=65}if(s.heritage?.familyId==='dragonCourt'&&[9,36].includes(s.race))x.access=83}const trust=35+x.access*.25;x.voice=Math.round(bound(x.voice+(trust-40)*.2));x.access=Math.round(bound(x.access+(trust-40)*.2));return x}
 function assessment(s,current=false){
  if(s.race===0){const h=s.humanOrigin,clan=h&&!h.migrated?(current?HumanOrigins.clan(h.clanId,s):WorldHistory.house(HumanOrigins.clan(h.clanId),WorldHistory.birth(s))):null,birthRank=h?.birthRank??s.heritage?.birthRank??s.rank;return {tier:clan&&(!current||s.rank===birthRank)?humanTypes[clan.type]:rankTiers[current?s.rank:birthRank],name:current?HumanOrigins.classLabel(s):clan?HumanOrigins.types.find(t=>t.id===clan.type).label:CLASSES[birthRank],basis:clan?clan.assets:'สิทธิ เครือข่าย และทรัพยากรของชั้นกำเนิด',burden:clan?.burden||'รายได้ส่วนตัวและความสัมพันธ์ยังเปลี่ยนได้',axes:null}}
  const a=SpeciesSociety.ensure(s),m=SpeciesSociety.profile(s),axes=current?SpeciesSociety.metrics(s):starting(s),score=bound(axes.resources*.3+axes.access*.35+axes.voice*.35);
  return {tier:grade(score),score:Math.round(score),name:current?SpeciesSociety.label(s):m.origins[a.origin],basis:m.res+' · '+m.access+' · '+m.voice,burden:m.duty,axes};
 }
 function report(s){return {species:species(s),origin:assessment(s),standing:assessment(s,true)}}
 return {order,rows,humanTypes,rankTiers,grade,species,starting,assessment,report};
